insert into publishers (name) values ('Copy.ai') on conflict (name) do nothing; insert into tools (name, slug, publisher_id, summary, description, official_url, status, pricing_model, price_display, api_available, open_source, local_available, keywords, strengths, limits, audience, last_verified_at) select 'Copy.ai', 'copy-ai', p.id, 'AI go-to-market platform for sales and marketing content workflows.', 'Copy.ai generates marketing copy and GTM workflows using AI agents and templates.', 'https://www.copy.ai', 'published', 'Freemium', 'Free / paid plans', true, false, false, ARRAY['copywriting', 'gtm', 'sales']::text[], ARRAY['GTM workflow focus']::text[], ARRAY['Output needs brand editing']::text[], ARRAY['Marketers', 'Sales']::text[], current_date from publishers p where p.name = 'Copy.ai' on conflict (slug) do nothing;
insert into publishers (name) values ('Writesonic') on conflict (name) do nothing; insert into tools (name, slug, publisher_id, summary, description, official_url, status, pricing_model, price_display, api_available, open_source, local_available, keywords, strengths, limits, audience, last_verified_at) select 'Writesonic', 'writesonic', p.id, 'AI writing and SEO content platform.', 'Writesonic helps create articles, ads and SEO-oriented content with templates and assistants.', 'https://writesonic.com', 'published', 'Freemium', 'Free trial / paid plans', true, false, false, ARRAY['seo', 'copywriting', 'articles']::text[], ARRAY['SEO content tooling']::text[], ARRAY['Quality varies; human edit recommended']::text[], ARRAY['Marketers', 'SMB']::text[], current_date from publishers p where p.name = 'Writesonic' on conflict (slug) do nothing;
insert into publishers (name) values ('Grammarly') on conflict (name) do nothing; insert into tools (name, slug, publisher_id, summary, description, official_url, status, pricing_model, price_display, api_available, open_source, local_available, keywords, strengths, limits, audience, last_verified_at) select 'Grammarly', 'grammarly', p.id, 'AI writing assistant for grammar, tone and clarity across apps.', 'Grammarly offers writing suggestions, rewrites and generative help in browser and desktop integrations.', 'https://www.grammarly.com', 'published', 'Freemium', 'Free / Premium / Business', true, false, false, ARRAY['grammar', 'tone', 'writing']::text[], ARRAY['Ubiquitous integrations', 'Strong editing UX']::text[], ARRAY['Generative depth below full chat LLMs']::text[], ARRAY['Professionals', 'Students']::text[], current_date from publishers p where p.name = 'Grammarly' on conflict (slug) do nothing;
